import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

/**
 * Semeia os QUATRO documentos oficiais da ENEL nas concessionárias — bucket
 * `concessionaire-templates`, mesma pasta dos Anexos E/F e dos memoriais,
 * em todos os tenants que tenham a ENEL (incluindo a biblioteca da GD Manager).
 *
 * Por que uma função e não upload pela tela: são quatro arquivos × um tenant
 * cada, e a mão erra. Aqui é idempotente e repetível — e é o mesmo mecanismo
 * que já semeou os memoriais (`seed-memorial-templates`).
 *
 * Cada documento é preenchido por um caminho diferente, e isso está anotado
 * no nome para quem for mexer depois:
 * - os dois ANEXOS são PDF **sem campos preenchíveis**: o sistema escreve
 *   texto por cima, em coordenadas fixas (`src/utils/formFill/enelForms.ts`);
 * - o MEMORIAL é .docx com tags `{chave}` — motor de templates de sempre;
 * - o FORMULÁRIO é .xlsx preenchido por célula (`src/utils/formFill/fillXlsx.ts`).
 *
 * Idempotente: se a concessionária já tiver arquivo com o mesmo nome-base,
 * pula. Para substituir, chame com `{"overwrite": true}`.
 *
 * Os originais ficam versionados em `docs/modelos-enel/`; aqui vão embutidos
 * em base64 para a função não depender de rede.
 * Regerar: `node scripts/build-seed-enel-forms.cjs`.
 */

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const BUCKET = 'concessionaire-templates';

const ANEXO1_B64 = '';
const ANEXO4_B64 = '';
const MEMORIAL_B64 = '';
const PLANILHA_B64 = '';

const TEMPLATES: { fileName: string; mime: string; base64: string }[] = [
  {
    fileName: 'ANEXO_1_SOLICITACAO_ACESSO.pdf',
    mime: 'application/pdf',
    base64: ANEXO1_B64,
  },
  {
    fileName: 'ANEXO_4_DADOS_UNIDADE_ACESSANTE.pdf',
    mime: 'application/pdf',
    base64: ANEXO4_B64,
  },
  {
    fileName: 'MEMORIAL_DESCRITIVO_ENEL_v2.docx',
    mime: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    base64: MEMORIAL_B64,
  },
  {
    fileName: 'FORMULARIO_REGISTRO_CENTRAL_GERADORA.xlsx',
    mime: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    base64: PLANILHA_B64,
  },
];

function bytesFromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  const json = (body: unknown, status = 200) =>
    new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

  try {
    const body = req.method === 'POST' ? await req.json().catch(() => ({})) : {};
    const overwrite = body?.overwrite === true;

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
    );

    const { data: concessionaires, error } = await supabase
      .from('energy_concessionaires')
      .select('id, name, tenant_id');
    if (error) return json({ ok: false, error: error.message }, 500);

    const alvos = (concessionaires ?? []).filter((c: { name: string }) => /enel/i.test(c.name));
    const results: unknown[] = [];

    for (const c of alvos as { id: string; name: string }[]) {
      // Lista a pasta UMA vez e filtra aqui dentro. Não dá para usar o
      // `search` do storage: ele casa pelo COMEÇO do nome, e os arquivos são
      // gravados como `{timestamp}_{nome}` — a busca nunca encontrava nada e
      // a função reenviava tudo a cada chamada (duplicou na primeira vez).
      const { data: naPasta } = await supabase.storage.from(BUCKET).list(c.id, { limit: 1000 });
      const arquivos = (naPasta ?? []) as { name: string; created_at?: string }[];

      // limpeza de duplicados: por nome-base, guarda o mais novo e apaga o resto
      if (body?.dedupe === true) {
        for (const tpl of TEMPLATES) {
          const iguais = arquivos
            .filter((f) => f.name.endsWith(tpl.fileName))
            .sort((a, b) => (b.name > a.name ? 1 : -1)); // o timestamp no nome ordena
          const sobrando = iguais.slice(1);
          if (sobrando.length === 0) continue;
          const { error: delErr } = await supabase.storage
            .from(BUCKET).remove(sobrando.map((f) => `${c.id}/${f.name}`));
          results.push(delErr
            ? { concessionaria: c.id, arquivo: tpl.fileName, status: 'erro', error: delErr.message }
            : { concessionaria: c.id, arquivo: tpl.fileName, status: 'duplicados_removidos', quantos: sobrando.length });
        }
        continue;
      }

      for (const tpl of TEMPLATES) {
        const already = arquivos.find((f) => f.name.endsWith(tpl.fileName));
        if (already && !overwrite) {
          results.push({ concessionaria: c.id, arquivo: tpl.fileName, status: 'ja_existia' });
          continue;
        }
        const fileName = already && overwrite ? already.name : `${Date.now()}_${tpl.fileName}`;
        const { error: upErr } = await supabase.storage
          .from(BUCKET)
          .upload(`${c.id}/${fileName}`, bytesFromBase64(tpl.base64), {
            contentType: tpl.mime,
            upsert: true,
          });
        results.push(upErr
          ? { concessionaria: c.id, arquivo: tpl.fileName, status: 'erro', error: upErr.message }
          : { concessionaria: c.id, arquivo: fileName, status: 'enviado' });
      }
    }

    const enviados = results.filter((r) => (r as { status: string }).status === 'enviado').length;
    const erros = results.filter((r) => (r as { status: string }).status === 'erro').length;
    return json({ ok: erros === 0, concessionarias: alvos.length, enviados, erros, results });
  } catch (e) {
    return json({ ok: false, error: e instanceof Error ? e.message : 'erro inesperado' }, 500);
  }
});
